    <Section style={{
    padding: [32, 24],
    gap: 12,
    alignItems: "center"
  }}>
      <Video src={FILM} thumbnail={thumbnail(Root, BENCH)} title="Cutting the tubes" style={{
      width: 320
    }} mobile={{
      width: "100%"
    }} />
      <Paragraph style={{
      ...CAPTION,
      textAlign: "center"
    }}>width: 320, the whole width on phones</Paragraph>
      <Video src={FILM} thumbnail={thumbnail(Root, PASS)} title="The first ride" style={{
      width: "50%"
    }} />
      <Paragraph style={{
      ...CAPTION,
      textAlign: "center"
    }}>width: "50%", half the space</Paragraph>
    </Section>
